    name: toStr(ctx.senderName) || (senderRole === "ORGANIZER" ? (toStr(game?.organizer?.name) || "Организатор") : "Игрок"),
    role: senderRole,
  },
  type: ctx.type || "TEXT",
  text: ctx.text,
  createdAt: nowIso,
  createdTs: nowTs,
  editedAt: null,
  deleted: false,
};

msg._chatMessageDoc = messageDoc;
msg.payload = messageDoc;
return [msg, null, msg];

